using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using LastRail.Auth;
using LastRail.Run;
using LastRail.Presentation.MissionShell;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {public sealed class BulkClaimValidationTests {
 sealed class Journal:IAccountActionJournal {public PendingAccountAction Row;public PendingAccountAction Read(string id)=>Row?.Account==id?Row:null;public bool Save(PendingAccountAction a){Row=a;return true;}public bool Remove(PendingAccountAction a){Row=null;return true;}}
 sealed class Wire:IRunApiHttpTransport {public List<RunApiHttpRequest> Requests=new List<RunApiHttpRequest>();public Func<RunApiHttpRequest,Task<RunApiHttpResponse>> Reply=r=>Task.FromResult(RunApiHttpResponse.NetworkError("lost"));public Task<RunApiHttpResponse> SendAsync(RunApiHttpRequest r){Requests.Add(r);return Reply(r);}}
 static GameApiAuthSessionSnapshot Session()=>new GameApiAuthSessionSnapshot("account_test","ACTIVE",new GameApiAccessToken("lst1.fixture"),DateTime.UtcNow.AddMinutes(5),new GameApiRefreshToken("fixture"),DateTime.UtcNow.AddMinutes(10));
 const string Body="{\"kind\":\"QUEST\",\"awardIds\":[\"first\",\"second\"]}";
 static JObject Result(bool complete=false){return new JObject{["accepted"]=true,["version"]="bulk-claim-v1",["bulkId"]="bulk_id",["request"]=JObject.Parse(Body),["createdAt"]=1000,["status"]=complete?"COMPLETE":"PARTIAL",["successCount"]=0,["failureCount"]=complete?2:1,["pendingCount"]=complete?0:1,["totalCount"]=2,["refreshRequired"]=false,["items"]=new JArray(new[]{"first","second"}.Select((id,i)=>new JObject{["index"]=i,["action"]=new JObject{["kind"]="QUEST",["awardId"]=id},["status"]=i==0||complete?"FAILED":"RETRY_PENDING",["receipt"]=null,["errorCode"]=i==0||complete?"quest_not_earned":null}))};}
 [Test] public void StrictOneKindUniqueFrozenMembershipAndExactCounters(){foreach(var invalid in new[]{"{\"kind\":\"QUEST\",\"awardIds\":[]}","{\"kind\":\"QUEST\",\"awardIds\":[\"a\",\"a\"]}","{\"kind\":\"MAIL\",\"awardIds\":[\"a\"],\"levels\":[1]}","{\"kind\":\"PASS_LEVEL\",\"policyId\":\"p\",\"track\":\"FREE\",\"levels\":[51]}"})Assert.Throws<FormatException>(()=>BulkClaimContract.Request(invalid));var data=Result();var parsed=new BulkClaimResult(data.ToString(),Body);Assert.That(parsed.Pending,Is.EqualTo(1));parsed.Items.Clear();Assert.That(parsed.Items.Count,Is.EqualTo(2));Assert.Throws<FormatException>(()=>new BulkClaimResult(data.ToString(),"{\"kind\":\"QUEST\",\"awardIds\":[\"second\",\"first\"]}"));data["successCount"]=2;Assert.Throws<FormatException>(()=>new BulkClaimResult(data.ToString(),Body));}
 [Test] public async Task UnknownReplyRetainsSameJournalBodyOrderAndKey(){var action=new PendingAccountAction("account_test","recurring-bulk","bulk",0,"original:/+",Body);var journal=new Journal{Row=action};var wire=new Wire();var session=Session();using var state=new AccountScreenRuntime(wire,journal,()=>session,()=>1);await state.RetryPendingAsync();wire.Reply=r=>Task.FromResult(RunApiHttpResponse.Success(200,"{\"accepted\":true}"));await state.ContinueBulkAsync();Assert.That(journal.Row,Is.SameAs(action));Assert.That(wire.Requests.Count,Is.EqualTo(2));Assert.That(wire.Requests.All(r=>r.BodyJson==Body&&r.EndpointPath=="/v1/recurring/bulk-claims"&&r.Headers.Single(h=>h.Name=="Idempotency-Key").Value==action.Key),Is.True);}
 [Test] public async Task PartialReadDoesNotResumeAndAllFailureCompleteIsNotSuccess(){var journal=new Journal{Row=new PendingAccountAction("account_test","recurring-bulk","bulk",0,"key",Body)};var wire=new Wire{Reply=r=>Task.FromResult(r.EndpointPath.StartsWith("/v1/recurring/bulk-claims")?RunApiHttpResponse.Success(200,Result().ToString()):RunApiHttpResponse.NetworkError("out of scope"))};var session=Session();using var state=new AccountScreenRuntime(wire,journal,()=>session,()=>1);await state.RetryPendingAsync();Assert.That(state.Pending,Is.Not.Null);var writes=wire.Requests.Count(r=>r.Method=="POST");await state.RefreshBulkResultAsync();Assert.That(wire.Requests.Count(r=>r.Method=="POST"),Is.EqualTo(writes));wire.Reply=r=>Task.FromResult(r.EndpointPath.StartsWith("/v1/recurring/bulk-claims")?RunApiHttpResponse.Success(200,Result(true).ToString()):RunApiHttpResponse.NetworkError("out of scope"));await state.ContinueBulkAsync();Assert.That(state.Pending,Is.Null);Assert.That(state.LastBulkResult.Complete,Is.True);Assert.That(state.LastBulkResult.Success,Is.Zero);Assert.That(state.LastBulkResult.Failed,Is.EqualTo(2));Assert.That(state.BulkNotice,Does.Contain("실패 2"));}
 [Test] public async Task OwnerChangeDoesNotConsumeOldBulkJournalOrPublishReply(){var action=new PendingAccountAction("account_test","recurring-bulk","bulk",0,"key",Body);var journal=new Journal{Row=action};var done=new TaskCompletionSource<RunApiHttpResponse>();var wire=new Wire{Reply=r=>done.Task};var session=Session();long generation=1;using var state=new AccountScreenRuntime(wire,journal,()=>session,()=>generation);var run=state.RetryPendingAsync();generation++;state.SynchronizeSession();done.SetResult(RunApiHttpResponse.Success(200,Result(true).ToString()));await run;Assert.That(journal.Row,Is.SameAs(action));Assert.That(state.LastBulkResult,Is.Null);}
} }
